<?php namespace App\Services;
class ContentTransformer { public function transform(string $html):array {$short=[];preg_match_all('/\[(vc_[a-z0-9_]+)/i',$html,$m);$short=array_values(array_unique($m[1]??[]));$unknown=array_values(array_diff($short,['vc_row','vc_column','vc_column_text','vc_message','vc_widget_sidebar','vc_raw_html']));$html=preg_replace('/\[\/?vc_(?:row|column)(?:\s[^\]]*)?\]/i','',$html);$html=preg_replace('/\[vc_column_text(?:\s[^\]]*)?\](.*?)\[\/vc_column_text\]/is','$1',$html);$html=preg_replace('/\[vc_message(?:\s[^\]]*)?\](.*?)\[\/vc_message\]/is','<aside class="legacy-message">$1</aside>',$html);$html=preg_replace('/\[vc_widget_sidebar[^\]]*\]/i','',$html);$html=preg_replace_callback('/\[vc_raw_html[^\]]*\](.*?)\[\/vc_raw_html\]/is',fn($x)=>htmlspecialchars_decode(trim($x[1]),ENT_QUOTES|ENT_HTML5),$html);return ['html'=>$html,'shortcodes'=>$short,'unknown'=>$unknown,'removed_sidebar'=>in_array('vc_widget_sidebar',$short,true)];}}
